<template>
  <button @click="exportPdf" class="pdf-export-btn">
    <i class="fa fa-file-pdf mr-2"></i>
    Exportar a PDF
  </button>
</template>

<script>
import jsPDF from "jspdf";
import html2canvas from "html2canvas";

export default {
  name: "PDFExport",
  props: {
    targetElement: {
      type: HTMLElement,
      required: false,
      default: null
    },
    orderData: {
      type: Object,
      required: false,
      default: null
    },
    iscombo: {
      type: Boolean,
      required: false,
      default: false
    },
    filename: {
      type: String,
      default: "orden.pdf"
    }
  },
  methods: {
    async exportPdf() {
      try {
        const pdf = new jsPDF("p", "mm", "a4");
        
        if (this.orderData) {
          await this.generatePdfFromTemplate(pdf);
        } else if (this.targetElement) {
          await this.generatePdfFromHtml(pdf);
        } else {
          console.error("Se requiere targetElement u orderData");
          return;
        }
        
        pdf.save(this.filename);
      } catch (error) {
        console.error("Error exportando PDF:", error);
        alert("Error al generar el PDF.");
      }
    },

    async generatePdfFromTemplate(pdf) {
      const order = this.orderData;
      const isCombo = this.iscombo;
      const margin = 15;
      let yPosition = margin;
      
      // ===== HEADER PRINCIPAL =====
      // Fondo gris para el header
      pdf.setFillColor(248, 249, 250); // bg-gray-50
      pdf.rect(0, 0, 210, 25, 'F');
      
      // Referencia de la orden - Izquierda
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(18);
      pdf.setTextColor(31, 41, 55); // gray-800
      pdf.text(`Orden ${order.reference}`, margin, yPosition + 8);
      
      // Total - Derecha
      const total = order.amount ? order.amount.toFixed(2) : '0.00';
      const totalamountdev = parseFloat(total);// + parseFloat(order.delivery.toFixed(2))
      const totalText = `$${totalamountdev}`;
      const totalWidth = pdf.getTextWidth(totalText);
      pdf.text(totalText, 210 - margin - totalWidth, yPosition + 8);
      
      // Línea separadora
      pdf.setDrawColor(209, 213, 219); // gray-300
      pdf.line(margin, 30, 210 - margin, 30);
      
      yPosition = 40;
      
      // ===== INFORMACIÓN DE ESTADO Y FECHA =====
      // Estado con badge de color
      const statusInfo = this.getStatusInfo(order.status);
      pdf.setFillColor(statusInfo.color.r, statusInfo.color.g, statusInfo.color.b);
      pdf.rect(margin, yPosition - 5, 40, 8, 'F');
      
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(10);
      pdf.setTextColor(255, 255, 255);
      pdf.text(`Estado: ${statusInfo.text}`, margin + 3, yPosition);
      
      // Fecha al lado del estado
      pdf.setTextColor(107, 114, 128); // gray-500
      pdf.setFont("helvetica", "normal");
      const orderDate = order.order_date ? new Date(order.order_date) : new Date();
      const formattedDate = orderDate.toLocaleDateString('es-ES', {
        day: 'numeric',
        month: 'short',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
      pdf.text(`Fecha: ${formattedDate}`, margin + 50, yPosition);
      
      // Total a la derecha
      pdf.setFont("helvetica", "bold");
      pdf.setTextColor(31, 41, 55);
      pdf.text("Total", 160, yPosition);
      pdf.text(totalText, 210 - margin - totalWidth, yPosition);
      
      yPosition += 20;
      
      // ===== INFORMACIÓN DEL CLIENTE =====
      // Título de sección
      pdf.setFillColor(243, 244, 246); // gray-100
      pdf.rect(margin, yPosition - 5, 80, 8, 'F');
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(12);
      pdf.setTextColor(31, 41, 55);
      pdf.text("Información del cliente", margin + 3, yPosition);
      
      yPosition += 10;
      
      // Datos del cliente con iconos simulados
      if (order.marketplace_contact) {
        const contact = order.marketplace_contact;
        
        // Nombre
        pdf.setFont("helvetica", "bold");
        pdf.setFontSize(10);
        pdf.setTextColor(75, 85, 99); // gray-600
        pdf.text("Nombre:", margin, yPosition);
        pdf.setTextColor(31, 41, 55);
        pdf.text(contact.name || '', margin + 20, yPosition);
        
        // Carnet
        yPosition += 6;
        pdf.setTextColor(75, 85, 99);
        pdf.text("Carnet:", margin, yPosition);
        pdf.setTextColor(31, 41, 55);
        pdf.text(contact.id_number || '', margin + 20, yPosition);
        
        // Teléfono
        yPosition += 6;
        pdf.setTextColor(75, 85, 99);
        pdf.text("Teléfono:", margin, yPosition);
        pdf.setTextColor(31, 41, 55);
        pdf.text(contact.phone || '', margin + 20, yPosition);
        
        // Dirección
        yPosition += 6;
        pdf.setTextColor(75, 85, 99);
        pdf.text("Dirección:", margin, yPosition);
        pdf.setTextColor(31, 41, 55);
        
        // Manejar dirección larga con wrap
        const address = contact.address || '';
        const addressLines = this.splitTextToLines(pdf, address, 80);
        addressLines.forEach((line, index) => {
          pdf.text(line, margin + 20, yPosition + (index * 4));
        });
        yPosition += (addressLines.length * 4) + 2;
      }
      
      pdf.setTextColor(75, 85, 99);
      pdf.text("Localidad:", margin, yPosition);
      pdf.setTextColor(31, 41, 55);
      pdf.text(order.city + ", " + order.province, margin + 20, yPosition);

      yPosition += 16;
      
      // ===== PRODUCTOS DEL PEDIDO =====
      // Título de sección
      pdf.setFillColor(243, 244, 246);
      pdf.rect(margin, yPosition - 5, 80, 8, 'F');
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(12);
      pdf.setTextColor(31, 41, 55);
      pdf.text("Productos del pedido", margin + 3, yPosition);
      
      yPosition += 10;
      
      // Header de la tabla
      pdf.setFillColor(249, 250, 251); // gray-50
      pdf.rect(margin, yPosition - 3, 180, 8, 'F');
      
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(10);
      pdf.setTextColor(55, 65, 81); // gray-700
      
      pdf.text("Producto", margin + 2, yPosition + 2);
      pdf.text("Cantidad", 120, yPosition + 2);
      pdf.text("Precio unit.", 150, yPosition + 2);
      pdf.text("Total", 180, yPosition + 2);
      
      // Línea separadora del header
      pdf.setDrawColor(229, 231, 235); // gray-200
      pdf.line(margin, yPosition + 4, 210 - margin, yPosition + 4);
      
      yPosition += 10;
      
      // Items de productos
      pdf.setFont("helvetica", "normal");
      pdf.setFontSize(9);
      
      if (order.items && order.items.length > 0) {
        let itemCount = 0;
        order.items.forEach(item => {
          // Verificar si necesita nueva página
          if (yPosition > 250) {
            pdf.addPage();
            yPosition = margin + 10;
          }
          
          // Fondo alternado para filas
          if (itemCount % 2 === 0) {
            pdf.setFillColor(255, 255, 255);
          } else {
            pdf.setFillColor(249, 250, 251);
          }
          pdf.rect(margin, yPosition - 2, 180, 8, 'F');
          
          // Nombre del producto
          pdf.setTextColor(31, 41, 55);
          const productName = this.splitTextToLines(pdf, item.name || 'Producto', 70)[0];
          pdf.text(productName, margin + 2, yPosition + 2);

          // En caso de que el producto sea combo pintar las features que tiene                    
          pdf.setFontSize(8);
          pdf.setTextColor(75, 85, 99);
          let yPos = yPosition;
          if(isCombo && item.features && item.features.length > 0) {
            yPos += 3;
            item.features.forEach(feature => {
              if(feature.title){
                pdf.text('- ' + feature.title + ': ' + feature.value, margin + 4, yPos + 4);
                yPos += 4;
              }
            });            
          }

          pdf.setFontSize(9);
          // Cantidad
          pdf.setTextColor(37, 99, 235); // blue-600
          pdf.text(`${item.quantity || 0}`, 120, yPosition + 2);
          
          // Precio unitario
          pdf.setTextColor(75, 85, 99);
          pdf.text(`$${(item.price_unit || 0).toFixed(2)}`, 150, yPosition + 2);
          
          // Total del item
          pdf.setTextColor(22, 163, 74); // green-600
          pdf.text(`$${(item.final_price || 0).toFixed(2)}`, 180, yPosition + 2);
          
          if(yPos > yPosition){
            yPosition = yPos;
          }
          yPosition += 8;
          itemCount++;
        });
      } else {
        pdf.setTextColor(156, 163, 175); // gray-400
        pdf.text("No hay productos en este pedido", margin + 2, yPosition + 2);
        yPosition += 8;
      }
      
      yPosition += 15;
      
      // ===== RESUMEN DE PAGO =====
      // Título de sección
      pdf.setFillColor(243, 244, 246);
      pdf.rect(margin, yPosition - 5, 60, 8, 'F');
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(12);
      pdf.setTextColor(31, 41, 55);
      pdf.text("Resumen de pago", margin + 3, yPosition);
      
      yPosition += 10;
      
      // Cálculos
      const subtotal = order.items ? order.items.reduce((sum, item) => sum + (item.price_unit * item.quantity || 0), 0) : 0;
      const totalDiscount = order.items ? order.items.reduce((sum, item) => sum + (item.discount || 0), 0) : 0;
      
      // Subtotales
      pdf.setFont("helvetica", "normal");
      pdf.setFontSize(10);
      pdf.setTextColor(75, 85, 99);
      pdf.text("Subtotal productos:", margin, yPosition);
      pdf.setTextColor(31, 41, 55);
      pdf.text(`$${subtotal.toFixed(2)}`, 210 - margin - pdf.getTextWidth(`$${subtotal.toFixed(2)}`), yPosition);
      
      yPosition += 6;
      
      // Descuentos si existen
      if (totalDiscount > 0) {
        pdf.setTextColor(75, 85, 99);
        pdf.text("Descuentos:", margin, yPosition);
        pdf.setTextColor(220, 38, 38); // red-600
        pdf.text(`-$${totalDiscount.toFixed(2)}`, 210 - margin - pdf.getTextWidth(`-$${totalDiscount.toFixed(2)}`), yPosition);
        yPosition += 6;
      }
      
      // Transportación
      if (order.delivery > 0) {
        pdf.setTextColor(75, 85, 99);
        pdf.text("Transportación:", margin, yPosition);
        pdf.setTextColor(31, 41, 55);
        pdf.text(`$${order.delivery.toFixed(2)}`, 210 - margin - pdf.getTextWidth(`$${order.delivery.toFixed(2)}`), yPosition);
        yPosition += 6;
      }
      
      yPosition += 4;
      
      // Total general
      pdf.setDrawColor(229, 231, 235);
      pdf.line(margin, yPosition, 210 - margin, yPosition);
      yPosition += 8;
      
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(14);
      pdf.setTextColor(22, 163, 74); // green-600
      pdf.text("Total a pagar:", margin, yPosition);
      const finalTotalText = `$${totalamountdev}`;
      pdf.text(finalTotalText, 210 - margin - pdf.getTextWidth(finalTotalText), yPosition);
      
      // ===== FOOTER =====
      const currentDate = new Date().toLocaleDateString('es-ES', {
        day: 'numeric',
        month: 'long',
        year: 'numeric'
      });
      
      pdf.setFont("helvetica", "normal");
      pdf.setFontSize(8);
      pdf.setTextColor(156, 163, 175); // gray-400
      pdf.text(`Documento generado el ${currentDate}`, margin, 290);
    },

    async generatePdfFromHtml(pdf) {
      const canvas = await html2canvas(this.targetElement, {
        scale: 2,
        useCORS: true,
        allowTaint: true
      });

      const pageWidth = pdf.internal.pageSize.getWidth();
      const pageHeight = pdf.internal.pageSize.getHeight();
      const margin = 10;

      const pdfUsableWidth = pageWidth - margin * 2;
      const pxPerMm = canvas.width / pdfUsableWidth;
      const pageHeightPx = Math.floor((pageHeight - margin * 2) * pxPerMm);

      let remainingHeightPx = canvas.height;
      let offsetY = 0;

      const pageCanvas = document.createElement("canvas");
      pageCanvas.width = canvas.width;
      pageCanvas.height = Math.min(pageHeightPx, canvas.height);
      const pageCtx = pageCanvas.getContext("2d");

      while (remainingHeightPx > 0) {
        pageCtx.clearRect(0, 0, pageCanvas.width, pageCanvas.height);
        pageCtx.drawImage(
          canvas,
          0,
          offsetY,
          canvas.width,
          pageCanvas.height,
          0,
          0,
          canvas.width,
          pageCanvas.height
        );

        const imgData = pageCanvas.toDataURL("image/png");
        const imgHeightMm = pageCanvas.height / pxPerMm;

        if (offsetY > 0) {
          pdf.addPage();
        }
        pdf.addImage(imgData, "PNG", margin, margin, pdfUsableWidth, imgHeightMm, undefined, "FAST");

        offsetY += pageCanvas.height;
        remainingHeightPx -= pageCanvas.height;

        if (remainingHeightPx > 0 && remainingHeightPx < pageHeightPx) {
          pageCanvas.height = remainingHeightPx;
        }
      }
    },

    getStatusInfo(status) {
      const statusMap = {
        'created': { text: 'Creada', color: { r: 165, g: 180, b: 252 } }, // indigo-300
        'sended': { text: 'Enviada', color: { r: 252, g: 211, b: 77 } }, // yellow-300
        'completed': { text: 'Completada', color: { r: 134, g: 239, b: 172 } }, // green-300
        'cancelled': { text: 'Cancelada', color: { r: 249, g: 168, b: 212 } } // pink-300
      };
      return statusMap[status] || { text: status, color: { r: 209, g: 213, b: 219 } }; // gray-300
    },

    splitTextToLines(pdf, text, maxWidth) {
      const words = text.split(' ');
      const lines = [];
      let currentLine = words[0];

      for (let i = 1; i < words.length; i++) {
        const word = words[i];
        const width = pdf.getTextWidth(currentLine + " " + word);
        if (width < maxWidth) {
          currentLine += " " + word;
        } else {
          lines.push(currentLine);
          currentLine = word;
        }
      }
      lines.push(currentLine);
      return lines;
    }
  }
};
</script>

<style scoped>
.pdf-export-btn {
  padding: 10px 16px;
  background-color: #dc2626;
  color: white;
  border: none;
  cursor: pointer;
  border-radius: 6px;
  font-weight: 600;
  transition: background-color 0.2s;
  font-size: 14px;
}
.pdf-export-btn:hover {
  background-color: #b91c1c;
  transform: translateY(-1px);
}
</style>