import Authorization from "../user/auth.service";

const baseUrl = "marketplace-report";
const HotelRoomPriceService = {
  async searchOrders(params) {
    try {
      params.auth = "bearer";

      const { type, ...info } = params;
      // console.log('Tipo de reporte:', type);
      const url = type == "statics" ? "statics" : "user-sales";

      const { status, data } = await Authorization.checkLogin(`/${baseUrl}/${url}`, info, "post");

      if (status == 200) {
        // Devolver los datos directamente
        return data; // ← Cambiado: ya no devuelves {data}
      }
    } catch (e) {
      console.error("Error en searchOrders:", e.response?.data || e.message);
    }
    return null; // ← Cambiado: null en lugar de false
  },

  // Este método parece no usarse, pero lo corregimos por si acaso
  async actionQuery(url, params) {
    try {
      params.auth = "bearer";
      const { status, data } = await Authorization.checkLogin(url, params, "post");
      if (status == 200) {
        return data; // ← Corregido: devolver data directamente
      }
    } catch (e) {
      console.error("Error en actionQuery:", e.response?.data || e.message);
    }
    return null;
  },
};

export default HotelRoomPriceService;
